import Link from "@/components/app-link";
import { DsdPracticePlanner } from "@/components/dsd-practice-planner";

export const metadata = { title: "Your practice plans" };

export default function PracticePlanPage() {
  return <article className="dsd-shell dsd-stage">
    <header className="dsd-page-heading"><p className="dsd-eyebrow">Preparing to act</p><h1>Your practice plans.</h1><p className="dsd-lede">Connect what you are learning with a decision or practice you can influence. Describe the question, consider the people affected, and identify an action and a way to review it.</p></header>
    <DsdPracticePlanner />
    <nav className="dsd-next" aria-label="Related work"><Link href="/my-work">My work</Link><Link href="/learn/equity-toolkit">Open the Equity Analysis Toolkit</Link></nav>
  </article>;
}

"use client";
import dynamic from "next/dynamic";
export const DsdPracticePlanner = dynamic(() => import("./dsd-practice-planner-editor"), {
  ssr: false,
  loading: () => <p role="status">Opening your practice plans…</p>,
});

import type { Metadata } from "next";
import Link from "@/components/app-link";
import { PageIntro } from "@/components/ui";
import { StructuralReviewWorkspace } from "@/components/structural-review-workspace";
import { ResourceDownloads } from "@/components/resource-downloads";

export const metadata: Metadata = {
  title: "Structural equity analysis",
  description: "Examine barriers in a DHS process, trace decision points, and develop an action with a responsible role and a review date.",
};

export default function StructuralReviewPage() {
  return <>
    <PageIntro tone="business" kicker="One DSD People, Access and Culture" title="Structural equity analysis" lede="Look closely at a process, identify where barriers arise, and connect evidence with a practical change.">
      <p className="mt-4 max-w-3xl">Use these eight steps for a policy, service, or workplace process anywhere in DHS. Work independently or with colleagues, and ask the Equity and Inclusion Operations Consultant for guidance when helpful.</p>
      <details className="border-b border-line pb-3 print:hidden"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#183247]">Download or share this page</summary><ResourceDownloads kind="equity-review" id="structural" noun="blank analysis" /></details>
    </PageIntro>
    <div className="wrap py-8">
      <nav className="mb-6 flex flex-wrap gap-5" aria-label="Related equity resources">
        <Link href="/equity-review">Equity review tools</Link>
        <Link href="/learn/equity-toolkit">Equity Analysis Toolkit</Link>
        <Link href="/support/right-person">Support and guidance</Link>
      </nav>
      <StructuralReviewWorkspace />
    </div>
  </>;
}

import { SourceLink } from "@/components/app-link";
import type { Metadata } from "next";
import Link from "@/components/app-link";
import { PageIntro } from "@/components/ui";
import { FocusedSections } from "@/components/focused-sections";
import styles from "@/components/director-toolkit.module.css";
import {
  DIRECTOR_FIRST_90_DAYS, DIRECTOR_STARTER_PACKAGE, DIRECTOR_TEMPLATES_HREF, DIRECTOR_TOOLKIT_INTRO, DIRECTOR_TOOLKIT_SECTIONS,
  directorTemplate, templateHref, type ToolkitItem, type ToolkitSection,
} from "@/lib/content/director-toolkit";
import { ResourceDownloads } from "@/components/resource-downloads";

export const metadata: Metadata = {
  title: "Equity Director toolkit",
  description: "Tools Equity Directors at the Minnesota Department of Human Services can use for equity work across the agency, with a first 90-day plan, a 12-item starter package and printable templates.",
};

function Item({ item }: { item: ToolkitItem }) {
  const template = item.templateId ? directorTemplate(item.templateId) : undefined;
  return <li className={styles.item}>
    <h3>{item.name}</h3>
    {item.publisher ? <p className={styles.publisher}>{item.publisher}</p> : null}
    <dl className={styles.facts}>
      <dt>What it is for</dt><dd>{item.purpose}</dd>
      <dt>How an Equity Director uses it</dt><dd>{item.use}</dd>
    </dl>
    {template || item.href || item.url ? <p className={styles.itemLinks}>
      {template ? <Link href={templateHref(template.id)}>Fill in the {template.title.replaceAll("\"", "")} template</Link> : null}
      {item.href ? <Link href={item.href}>Open the related page</Link> : null}
      {item.url ? <SourceLink href={item.url}>Open the published resource</SourceLink> : null}
    </p> : null}
  </li>;
}

function FirstNinetyDays() {
  return <div className={styles.tableWrap}><table className={styles.plan}>
    <caption className="sr-only">First 90 days: priority actions and deliverables for each period</caption>
    <thead><tr><th scope="col">Period</th><th scope="col">Priority actions</th><th scope="col">Deliverables</th></tr></thead>
    <tbody>{DIRECTOR_FIRST_90_DAYS.map(period => <tr key={period.id} id={period.id}>
      <th scope="row">{period.period}</th>
      <td><ul>{period.actions.map(action => <li key={action}>{action}</li>)}</ul></td>
      <td><ul>{period.deliverables.map(deliverable => <li key={deliverable}>{deliverable}</li>)}</ul></td>
    </tr>)}</tbody>
  </table></div>;
}

function StarterPackage() {
  return <ol className={styles.starter}>{DIRECTOR_STARTER_PACKAGE.map(item => <li key={item.number}>
    <p><span className={styles.num}>{item.number}.</span><Link href={item.href}>{item.title}</Link></p>
    <p>{item.detail}</p>
  </li>)}</ol>;
}

function Section({ section }: { section: ToolkitSection }) {
  const prominent = section.id === "first-90-days" || section.id === "starter-package";
  return <section id={section.id} aria-labelledby={`${section.id}-title`} className={prominent ? styles.highlight : styles.section}>
    <p className={styles.sectionNumber}>Section {section.number}</p>
    <h2 id={`${section.id}-title`} className="text-2xl font-bold">{section.title}</h2>
    <p className={styles.question}>{section.question}</p>
    {section.intro.map(paragraph => <p key={paragraph}>{paragraph}</p>)}
    {section.id === "first-90-days" ? <FirstNinetyDays /> : null}
    {section.id === "starter-package" ? <StarterPackage /> : null}
    {section.items.length ? <ul className={styles.items}>{section.items.map(item => <Item key={item.name} item={item} />)}</ul> : null}
    {section.lists?.map(list => <div key={list.heading} className="mt-5">
      <h3 className="text-xl font-bold">{list.heading}</h3>
      <ul className="list-disc pl-6">{list.items.map(entry => <li key={entry}>{entry}</li>)}</ul>
      {list.note ? <p>{list.note}</p> : null}
    </div>)}
    {section.caution ? <p className={styles.caution}><strong>Important: </strong>{section.caution}</p> : null}
    {section.notes?.map(note => <p key={note}>{note}</p>)}
    {section.related?.length ? <p className={styles.itemLinks}>{section.related.map(link => <Link key={link.href} href={link.href}>{link.label}</Link>)}</p> : null}
  </section>;
}

export default function DirectorToolkitPage() {
  return <>
    <PageIntro tone="business" kicker="Equity in practice" title={DIRECTOR_TOOLKIT_INTRO.title} lede={DIRECTOR_TOOLKIT_INTRO.lede}>
      <p className="mt-4 max-w-3xl"><Link href={DIRECTOR_TEMPLATES_HREF}>Open the 14 printable templates</Link></p>
      <details className="border-b border-line pb-3 print:hidden"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#183247]">Download or share this page</summary><ResourceDownloads kind="equity-review" id="director-toolkit" noun="toolkit" /></details>
    </PageIntro>
    <div className="wrap py-10">
      <FocusedSections>
        <section aria-labelledby="overview-title">
          <h2 id="overview-title" className="text-2xl font-bold">Overview</h2>
          {DIRECTOR_TOOLKIT_INTRO.summary.map(paragraph => <p key={paragraph}>{paragraph}</p>)}
          <p className="notice">{DIRECTOR_TOOLKIT_INTRO.privacy}</p>
        </section>
        <section id="start-here" aria-labelledby="start-here-title" className={styles.highlight}>
          <h2 id="start-here-title" className="text-2xl font-bold">Start here</h2>
          <p>New to the role, or starting a new equity effort? Begin with two things.</p>
          <ul className="list-disc pl-6">
            <li><SourceLink href="#first-90-days">The first 90 days</SourceLink>: what to do in each 30-day period, and what each period should produce.</li>
            <li><SourceLink href="#starter-package">The 12-item priority starter package</SourceLink>: three foundational DHS resources and nine practical supports to build with the people responsible for each area.</li>
            <li><Link href={DIRECTOR_TEMPLATES_HREF}>The printable templates</Link>: fill them in on screen, then print, copy or download a record. The app does not autosave or submit your entries.</li>
          </ul>
        </section>
        {DIRECTOR_TOOLKIT_SECTIONS.map(section => <Section key={section.id} section={section} />)}
        <nav aria-label="Related resources" className="flex flex-wrap gap-6">
          <Link href="/equity-review">Equity review tools</Link>
          <Link href="/equity-policy">DHS equity policy</Link>
          <Link href="/learn/equity-toolkit">Equity Analysis Toolkit companion</Link>
          <Link href="/operationalizing-equity">Operationalizing Equity</Link>
          <Link href="/support/right-person">Find the person or area responsible</Link>
        </nav>
      </FocusedSections>
    </div>
  </>;
}

import { FocusedSections } from "@/components/focused-sections";

import { SourceLink } from "@/components/app-link";
import type { Metadata } from "next";
import Link from "@/components/app-link";
import { PageIntro } from "@/components/ui";
import { DirectorToolkitTemplate } from "@/components/director-toolkit-template";
import styles from "@/components/director-toolkit.module.css";
import { DIRECTOR_TEMPLATES, DIRECTOR_TOOLKIT_HREF, DIRECTOR_TOOLKIT_SECTIONS, TEMPLATE_KEEP_OUT, templateAnchor } from "@/lib/content/director-toolkit";
import { ResourceDownloads } from "@/components/resource-downloads";

export const metadata: Metadata = {
  title: "Equity Director toolkit templates",
  description: "Fourteen printable fill-in templates for equity reviews at the Minnesota Department of Human Services. The app does not autosave or submit template entries.",
};

export default function DirectorToolkitTemplatesPage() {
  const sectionTitle = (id: string) => DIRECTOR_TOOLKIT_SECTIONS.find(section => section.id === id)?.title ?? "Equity Director toolkit";
  return <>
    <div className={styles.printHide}>
      <PageIntro tone="business" kicker="Equity Director toolkit" title="Printable templates" lede="Fill-in templates for equity reviews at the Minnesota Department of Human Services (DHS). Fill them in on screen, then print, copy or download.">
        <p className="mt-4 max-w-3xl"><Link href={DIRECTOR_TOOLKIT_HREF}>Back to the Equity Director toolkit</Link></p>
        <details className="border-b border-line pb-3 print:hidden"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#183247]">Download or share this page</summary><ResourceDownloads kind="equity-review" id="templates" noun="set of blank templates" /></details>
      </PageIntro>
    </div>
    <div className="wrap max-w-5xl space-y-10 py-10"><FocusedSections>
      <section aria-labelledby="templates-about" className={styles.printHide}>
        <h2 id="templates-about" className="text-2xl font-bold">Before you start</h2>
        <p>These templates put the DHS Equity Policy, the DHS Equity Analysis Toolkit and the State of Minnesota Equity Analysis Toolkit into practice. They do not replace them. Adapt each one with the people responsible for the work it covers.</p>
        <p className="notice">These templates run in your browser. The app does not autosave or submit your entries. Copy, download or print if you need a record before leaving this page. {TEMPLATE_KEEP_OUT}</p>
        <h3 className="mt-6 text-xl font-bold">The 14 templates</h3>
        <ol className={styles.templateIndex}>{DIRECTOR_TEMPLATES.map(template => <li key={template.id}><SourceLink href={`#${templateAnchor(template.id)}`}>{template.title}</SourceLink></li>)}</ol>
      </section>
      {DIRECTOR_TEMPLATES.map(template => <section key={template.id} id={`topic-${template.id}`} data-topic-title={template.title}><DirectorToolkitTemplate template={template} sectionTitle={sectionTitle(template.sectionId)} /></section>)}
      <nav aria-label="Related resources" className={`flex flex-wrap gap-6 ${styles.printHide}`}>
        <Link href={DIRECTOR_TOOLKIT_HREF}>Equity Director toolkit</Link>
        <Link href="/equity-review">Equity review tools</Link>
        <Link href="/equity-review/structural">Structural equity analysis</Link>
        <Link href="/practice/measurement">Measurement and evaluation</Link>
      </nav>
    </FocusedSections></div>
  </>;
}

import type { Metadata } from "next";
import Link from "@/components/app-link";
import { EditableSurfaceRegion, prepareEditableSurface } from "@/components/editable-surface";
import { stringValue } from "@/lib/content/staff-surface-registry";
import { ORGANIZATIONS } from "@/lib/content/hub/organizations";
import { OUTREACH_TASKS, outreachSteps } from "@/lib/content/hub/outreach-home";
import { ResourceDownloads } from "@/components/resource-downloads";
import styles from "./hub.module.css";

export const metadata: Metadata = {
  title: "Community Outreach and Engagement",
  description: "Prepare to work with Minnesota communities, find organizations connected with the Disability Services Division, and involve people in decisions.",
};

export default async function CommunityOutreachPage() {
  const surface = await prepareEditableSurface("community-outreach.home");
  const text = (key: string) => stringValue(surface.values, key);
  const steps = outreachSteps(ORGANIZATIONS.length);
  return <EditableSurfaceRegion surface={surface}>
    <div className={styles.page}>
      <header>
        <p className={styles.kicker}>{text("kicker")}</p>
        <h1 className={styles.title}>{text("title")}</h1>
        <p className={styles.lede}>{text("lede")}</p>
        {surface.available ? <details className="border-b border-line pb-3 print:hidden"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#183247]">Download or share this page</summary><ResourceDownloads kind="community-outreach" id="home" noun="page" /></details> : null}
      </header>

      <section className={styles.section} aria-labelledby="tasks-title">
        <h2 id="tasks-title">{text("tasksTitle")}</h2>
        <ul className="pilot-topic-rows">
          {OUTREACH_TASKS.map(task => <li key={task.href}><Link href={task.href}>
            <strong>{task.title}</strong><span>{task.body}</span>
          </Link></li>)}
        </ul>
      </section>

      <details className={styles.section}>
        <summary className="min-h-11 cursor-pointer font-semibold" id="cycle-title">{text("cycleTitle")}</summary>
        <p>{text("cycleIntro")}</p>
        <ol className={styles.cycle}>
          {steps.map(step => <li className={styles.step} key={step.key}><div>
            <h3>{text(`step${step.key}Title`)}</h3>
            <p>{text(`step${step.key}`)}</p>
            <p className={styles.capability}>{step.capability}</p>
            <ul className={styles.links}>{step.links.map(link => <li key={link.href}><Link href={link.href}>{link.label}</Link></li>)}</ul>
          </div></li>)}
        </ol>
      </details>

      <details className={styles.section}>
        <summary className="min-h-11 cursor-pointer font-semibold" id="care-title">Before you use the figures and the directory</summary>
        <p className={styles.note}>{text("numbersNote")}</p>
        <p>{text("tribalNote")} <Link href="/learn/tribal-referral">Native American and Tribal-specific guidance</Link>.</p>
        <p>{text("privacyNote")}</p>
      </details>
    </div>
  </EditableSurfaceRegion>;
}

import { catPaginate } from "@/lib/cat-paging";
import { CatPager, CatResultStatus } from "@/components/cat-list";

import { SourceLink } from "@/components/app-link";
import type { Metadata } from "next";
import Link from "@/components/app-link";
import { communityDesignEntries } from "@/lib/content/community-design";
import { isNativeCommunity } from "@/lib/content/hub/organizations";
import { SOURCING_CATEGORIES, SOURCING_CHECKED, SOURCING_USES, sourcingEntries } from "@/lib/content/hub/sourcing";
import styles from "../hub.module.css";
import { ResourceDownloads } from "@/components/resource-downloads";

export const metadata: Metadata = {
  title: "Where to reach people",
  description: "Potential sources for recruitment, outreach and engagement in Minnesota: colleges, workforce programs, associations, media, community places and events.",
};

export default async function SourcesPage({ searchParams }: { searchParams: Promise<{ category?: string; use?: string; community?: string; q?: string; page?: string }> }) {
  const { category = "", use = "", community = "", q = "", page: pageNumber } = await searchParams;
  const titles = new Map(communityDesignEntries().map(entry => [entry.id, entry.title]));
  const all = sourcingEntries();
  const communities = [...new Set(all.flatMap(entry => entry.communities))].filter(id => !isNativeCommunity(id) && titles.has(id))
    .sort((a, b) => (titles.get(a) ?? a).localeCompare(titles.get(b) ?? b));
  const query = q.trim().toLowerCase();
  const shown = all.filter(entry =>
    (!category || entry.category === category) &&
    (!use || entry.uses.includes(use as (typeof SOURCING_USES)[number])) &&
    (!community || entry.communities.includes(community)) &&
    (!query || `${entry.name} ${entry.alsoKnownAs ?? ""} ${entry.what} ${entry.region} ${(entry.languages ?? []).join(" ")}`.toLowerCase().includes(query)));
  const paging = catPaginate(shown, pageNumber ?? "", 8);
  const groups = SOURCING_CATEGORIES.map(c => ({ ...c, entries: paging.items.filter(entry => entry.category === c.category) })).filter(c => c.entries.length);
  return <div className={styles.page}>
    <p className={styles.kicker}><Link href="/community-outreach">Community Outreach and Engagement</Link></p>
    <h1 className={styles.title}>Where to reach people</h1>
    <p className={styles.lede}>Places to find job candidates, share information and involve community members across Minnesota: colleges, workforce programs, professional associations, media, community places and events.</p>
    <details className="border-b border-line pb-3 print:hidden"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#183247]">Download or share this page</summary><ResourceDownloads kind="community-outreach" id="sources" noun="source list" /></details>
    <p className={styles.note}>These are possible sources, not partners. Being listed does not mean a source works with the Department of Human Services or speaks for a community. Where a public record of a connection exists, the entry says so. Facts were checked on {SOURCING_CHECKED}; confirm current details before you rely on them.</p>
    <p>For Tribal colleges, Tribal Nations and Native American organizations, contact the Office of Indian Affairs and the Department of Human Services offices that handle Tribal relations and consultation. <Link href="/learn/tribal-referral">Native American and Tribal-specific guidance</Link>.</p>

    <form method="get" className={styles.filters} role="search" aria-label="Filter sources">
      <label>Type of source<select name="category" defaultValue={category}><option value="">All types</option>{SOURCING_CATEGORIES.map(c => <option key={c.category} value={c.category}>{c.title}</option>)}</select></label>
      <label>Use<select name="use" defaultValue={use}><option value="">All uses</option>{SOURCING_USES.map(u => <option key={u} value={u}>{u}</option>)}</select></label>
      <label>Community<select name="community" defaultValue={community}><option value="">All communities</option>{communities.map(id => <option key={id} value={id}>{titles.get(id)}</option>)}</select></label>
      <label>Search<input name="q" type="search" defaultValue={q} /></label>
      <button className={styles.button} type="submit">Show sources</button>
      {category || use || community || q ? <Link href="/community-outreach/sources">Clear filters</Link> : null}
    </form>
    <CatResultStatus page={paging} noun="source" nouns="sources" />

    {groups.length ? groups.map(group => <section className={styles.section} key={group.category} aria-labelledby={`group-${group.category}`}>
      <h2 id={`group-${group.category}`}>{group.title}</h2>
      <p>{group.intro}</p>
      <ul className={styles.grid} style={{ listStyle: "none", padding: 0 }}>
        {group.entries.map(entry => <li className={styles.card} key={`${entry.name}-${entry.region}`}>
          <h3>{entry.website ? <SourceLink href={entry.website}>{entry.name}</SourceLink> : entry.name}</h3>
          <p className={styles.meta}>{[entry.kind, entry.region].filter(Boolean).join(" · ")}</p>
          <div>{entry.uses.map(u => <span className={styles.chip} key={u}>{u}</span>)}</div>
          <p>{entry.what}</p>
          <p className={styles.small}>{entry.howToUse}</p>
          {entry.languages?.length ? <p className={styles.small}>Languages: {entry.languages.join(", ")}</p> : null}
          {entry.communities.some(id => titles.has(id)) ? <p className={styles.small}>Communities: {entry.communities.filter(id => titles.has(id)).map(id => titles.get(id)).join(", ")}</p> : null}
          {entry.contact ? <p className={styles.small}>Contact: {entry.contact}</p> : null}
          {entry.dhsRecord ? <p className={styles.small}>Department of Human Services record: {entry.dhsRecord}</p> : null}
        </li>)}
      </ul>
    </section>) : <p>No source matches these filters. <Link href="/community-outreach/sources">Show all sources</Link>.</p>}
    <CatPager page={paging} basePath="/community-outreach/sources" params={{category,use,community,q}} label="Source pages" />
  </div>;
}

import { SourceLink } from "@/components/app-link";
import type { Metadata } from "next";
import Link from "@/components/app-link";
import { notFound } from "next/navigation";
import { communityDesignEntries } from "@/lib/content/community-design";
import { ORGANIZATIONS, getOrganization, relationshipLine } from "@/lib/content/hub/organizations";
import { PrintPageButton } from "@/components/hub/print-page-button";
import styles from "../../hub.module.css";
import { ResourceDownloads } from "@/components/resource-downloads";
import { PrintOpenPanels } from "@/components/rp-print-open-panels";

export function generateStaticParams() {
  return ORGANIZATIONS.map(org => ({ slug: org.slug }));
}

export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }): Promise<Metadata> {
  const org = getOrganization((await params).slug);
  return org ? { title: `${org.name} (Community Outreach and Engagement)`, description: org.summary } : { title: "Organization" };
}

export default async function OrganizationPage({ params }: { params: Promise<{ slug: string }> }) {
  const org = getOrganization((await params).slug);
  if (!org) notFound();
  const titles = new Map(communityDesignEntries().map(entry => [entry.id, entry.title]));
  const contact = [
    org.contact.website ? <SourceLink key="w" href={org.contact.website}>{org.contact.website}</SourceLink> : null,
    org.contact.phone ? <span key="p">{org.contact.phone}</span> : null,
    org.contact.email ? <SourceLink key="e" href={`mailto:${org.contact.email}`}>{org.contact.email}</SourceLink> : null,
  ].filter(Boolean);
  return <article className={`${styles.page} pilot-reading-width`}>
    <p className={`${styles.kicker} ${styles.noPrint}`}><Link href="/community-outreach">Community Outreach and Engagement</Link> · <Link href="/community-outreach/organizations">Organizations</Link></p>
    <p className={styles.kicker}>{org.kind}</p>
    <h1 className={styles.title}>{org.name}</h1>
    {org.alsoKnownAs ? <p className={styles.meta}>Also known as {org.alsoKnownAs}</p> : null}
    <div>{org.relationshipTypes.map(t => <span className={styles.chip} key={t}>{t}</span>)}</div>
    {org.closed ? <p className={styles.note}>This organization has closed, according to its own website. It is listed for the record of its work with the Disability Services Division, not as a place to refer people.</p> : null}
    <p className={styles.lede}>{org.summary}</p>
    <details className="border-b border-line pb-3 print:hidden"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#183247]">Download or share this page</summary><ResourceDownloads kind="organization" id={org.slug} noun="organization page" /></details>

    <div className="mt-8 space-y-8">
      <section><h2 className="text-lg font-bold">Who it serves</h2><p>{org.whoItServes || "Not confirmed in the public records."}</p></section>
      <section><h2 className="text-lg font-bold">What it does</h2>{org.services.length ? <ul className="list-disc pl-6">{org.services.map(s => <li key={s}>{s}</li>)}</ul> : <p>Not confirmed in the public records.</p>}</section>
    </div>

    <section className={styles.section}>
      <h2>When staff might connect</h2>
      <p>{org.whyItMattersForStaff}</p>
      {org.communities.length ? <p>Community pages: {org.communities.map((id, i) => <span key={id}>{i ? ", " : ""}<Link href={`/minnesota-communities/${id}`}>{titles.get(id) ?? id}</Link></span>)}</p> : null}
      <p className={styles.noPrint}><Link href="/community-outreach/plan">Plan an engagement before you reach out</Link></p>
    </section>

    <section className={styles.section}>
      <h2>Contact</h2>
      <p>{contact.length ? contact.map((item, i) => <span key={i}>{i ? " · " : ""}{item}</span>) : "No general contact details were found in public sources."}</p>
    </section>

    <section className={styles.section}>
      <h2>More about this organization</h2>
      <details className="course-more-item">
        <summary>Where it works</summary>
        <p>{org.whereItWorks || "Not confirmed in the public records."}</p>
      </details>

      <details className="course-more-item">
        <summary>Work with the Disability Services Division and the Department of Human Services</summary>
