import styles from "../../../../courses/course-design.module.css";
import Link from "@/components/app-link";
import { notFound } from "next/navigation";
import { CourseLesson } from "@/components/course-lesson";
import { PlainLanguageComparison } from "@/components/multimedia/plain-language-comparison";
import { CriticalIncidentScene } from "@/components/multimedia/critical-incident-scene";
import { LearningCompanion } from "@/components/multimedia/learning-companion";
import { prepareEditableSurface } from "@/components/editable-surface";
import { getEditableSurfaceDefinition } from "@/lib/content/staff-surface-registry";
import { CoursePackSchema } from "@/lib/content/courses/contract";
import { courseText, sanitizedLesson, lessonObjectives } from "@/lib/content/courses/published";
import { requestedContentScope } from "@/lib/product/request-context";
import { ResourceDownloads } from "@/components/resource-downloads";
import { TRAINING_CREDIT_NOTICE } from "@/lib/program/learning-credit";
import type { Metadata } from "next";
import "../../../../courses/courses.css";

export const dynamic = "force-dynamic";

function shareCourseHref(courseId: string, lessonId?: string) {
  return `/share/courses/${encodeURIComponent(courseId)}${lessonId ? `/${encodeURIComponent(lessonId)}` : ""}`;
}

export async function generateMetadata({ params }: { params: Promise<{ courseId: string; lessonId: string }> }): Promise<Metadata> {
  const { courseId, lessonId } = await params;
  if (!getEditableSurfaceDefinition(`course.${courseId}`)) return {};
  const surface = await prepareEditableSurface(`course.${courseId}`, { scope: await requestedContentScope(), includeOwner: false });
  if (!surface.available) return {};
  const { course } = CoursePackSchema.parse(surface.values.pack);
  const lesson = course.lessons.find((item) => item.id === lessonId);
  return lesson ? { title: `${lesson.title} · ${course.title}`, description: courseText(lesson.summary) } : {};
}

/**
 * Opened by a shared link only. Previous/next and the course-overview
 * fallback all stay inside /share/courses so the course stays isolated. The
 * program view (One DHS or One DSD) follows the same request context as
 * every other page, so a link shared from the One DSD view opens the One DSD
 * version here too.
 */
export default async function SharedLessonPage({ params }: { params: Promise<{ courseId: string; lessonId: string }> }) {
  const { courseId, lessonId } = await params;
  if (!getEditableSurfaceDefinition(`course.${courseId}`)) notFound();
  const scope = await requestedContentScope();
  const surface = await prepareEditableSurface(`course.${courseId}`, { scope, includeOwner: false });
  if (!surface.available) notFound();
  const { course } = CoursePackSchema.parse(surface.values.pack);
  const index = course.lessons.findIndex((lesson) => lesson.id === lessonId);
  if (index < 0) notFound();
  const lesson = course.lessons[index];
  return (
    <div className={`course-page ${styles.page}`}>
      <Link className={styles.breadcrumb} href={shareCourseHref(courseId)}>{course.title}</Link>
      <div className={styles.lessonLayout}>
        <div className={styles.lessonMain}>
          <details className="border-b border-line pb-3 print:hidden"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#183247]">Download or share this lesson</summary><ResourceDownloads kind="lesson" id={`${courseId}~${lessonId}`} noun="lesson" scope={scope} /></details>
          <CourseLesson
            key={`${courseId}:${lessonId}`}
            courseId={courseId}
            courseOverviewHref={shareCourseHref(courseId)}
            companion={
              <>
                <LearningCompanion courseId={courseId} lessonId={lessonId} />
                {courseId === "plain-language-in-human-services" && lessonId === "pl-how" ? <PlainLanguageComparison /> : courseId === "critical-incidents-in-the-work" && lessonId === "ci-write" ? <CriticalIncidentScene /> : null}
              </>
            }
            lesson={sanitizedLesson(lesson)}
            objectives={lessonObjectives(lesson)}
            previous={index > 0 ? shareCourseHref(courseId, course.lessons[index - 1].id) : undefined}
            next={index < course.lessons.length - 1 ? shareCourseHref(courseId, course.lessons[index + 1].id) : undefined}
          />
          <p className={styles.credit}>{TRAINING_CREDIT_NOTICE}</p>
        </div>
        <nav className={styles.outline} aria-label="Course lessons">
          <h2>Explore this course</h2>
          <ol>
            {course.lessons.map((item) => (
              <li key={item.id}><Link href={shareCourseHref(courseId, item.id)} aria-current={item.id === lessonId ? "page" : undefined}>{item.title}</Link></li>
            ))}
          </ol>
        </nav>
      </div>
    </div>
  );
}

import { SourceLink } from "@/components/app-link";
import styles from "../../../resources/resource-design.module.css";
import type { Metadata } from "next";
import { notFound, redirect } from "next/navigation";
import {selfDirectedHref} from '@/lib/content/self-directed';
import { ResourceMediaGallery } from "@/components/resource-media-gallery";
import { ResourceDownloads } from "@/components/resource-downloads";
import { ActionList, AuthorityPill, Notice } from "@/components/ui";
import { getPublishedStaffContent } from "@/lib/content/staff-publications";
import { AUTHORITY, CONTENT_TYPE_LABEL, LAYER_LABEL } from "@/lib/content/types";
import { prepareEditableSurface } from "@/components/editable-surface";
import { requestedContentScope } from "@/lib/product/request-context";
import { stringValue } from "@/lib/content/staff-surface-registry";

export const dynamic = "force-dynamic";

export async function generateMetadata({ params }: { params: Promise<{ id: string }> }): Promise<Metadata> {
  const { id } = await params;
  const c = await getPublishedStaffContent(id, { scope: await requestedContentScope() });
  return { title: c ? c.title : "Resource" };
}

/**
 * Opened by a shared link only. It shows one library resource on its own,
 * with no navigation into the rest of the program — see /resources/[id] for
 * the same resource inside the full staff experience. The program view
 * (One DHS or One DSD) follows the same request context as every other page,
 * so a link shared from the One DSD view opens the One DSD version here too.
 */
export default async function SharedResourcePage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const courseHref=selfDirectedHref(id);
  if(courseHref)redirect(courseHref);
  const scope = await requestedContentScope();
  const [c, shellSurface] = await Promise.all([
    getPublishedStaffContent(id, { scope }),
    prepareEditableSurface("library.resource-shell", { scope, includeOwner: false }),
  ]);
  if (!c || c.status !== "approved") notFound();
  const shell = shellSurface.values;
  const isList = c.type === "checklist" || c.type === "question_bank";

  return (
    <div className={styles.page}>
      <header className={styles.hero}>
        <div className={styles.heroInner}>
          <p className={styles.eyebrow}>{CONTENT_TYPE_LABEL[c.type]} · {LAYER_LABEL[c.layer]}</p>
          <h1>{c.title}</h1>
          <p className={styles.lede}>{c.summary}</p>
          <ResourceMediaGallery contentItemId={c.id} owner={false} />
          <details className="mt-4 border-t border-line pt-4"><summary className="cursor-pointer font-semibold text-[#123f60]">Download this resource</summary><ResourceDownloads kind="library" id={c.id} scope={scope} /></details>
        </div>
      </header>
      <div className={styles.content}>
        <p className={styles.authority}>
          <AuthorityPill authority={c.authority} /> <span className="text-sm text-muted">{AUTHORITY[c.authority].staffNote}</span>
        </p>
        {c.authority === "external_verify" ? (
          <Notice tone="warn">
            {stringValue(shell, "outsideSourceNote")}
            {c.href ? (
              <>
                {" "}
                <SourceLink href={c.href} rel="noreferrer">
                  {stringValue(shell, "openSourceLabel")} ({c.sourceName ?? stringValue(shell, "sourceWebsiteLabel")})
                </SourceLink>
                .
              </>
            ) : (
              <> {stringValue(shell, "intranetSourceNote")}</>
            )}
          </Notice>
        ) : null}
        {c.whyItMatters ? (
          <div className={styles.why}>
            <p className="kicker">{stringValue(shell, "whyKicker")}</p>
            <p className="m-0">{c.whyItMatters}</p>
          </div>
        ) : null}
        <section className={styles.reading} aria-label="Content">
          {isList ? (
            <ol className="list-decimal space-y-2 pl-6">
              {c.body.map((p) => (
                <li key={p}>{p}</li>
              ))}
            </ol>
          ) : (
            <div className="space-y-3">
              {c.body.map((p) => (
                <p key={p} className="m-0">
                  {p}
                </p>
              ))}
            </div>
          )}
        </section>
        {(() => {
          const externalActions = c.nextActions.filter((action) => action.href.startsWith("http"));
          return externalActions.length ? <ActionList heading={stringValue(shell, "nextStepsTitle")} actions={externalActions} /> : null;
        })()}
        <p className="text-sm text-muted mt-6">You&rsquo;re viewing a shared link to this resource only. It doesn&rsquo;t include the rest of the program.</p>
      </div>
    </div>
  );
}

